import sqlite3
import time
import string
import urllib.parse
from typing import Optional, Dict, Union, Tuple

class URLRedirectService:
    def __init__(self, db_path: str = ":memory:") -> None:
        self.db_path = db_path
        try:
            self.conn = sqlite3.connect(self.db_path, check_same_thread=False)
            self._create_table()
        except sqlite3.Error as e:
            raise RuntimeError(f"Failed to initialize database connection: {e}")

    def _create_table(self) -> None:
        try:
            cursor = self.conn.cursor()
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS urls (
                    short_code TEXT PRIMARY KEY,
                    destination_url TEXT NOT NULL,
                    expires_at INTEGER
                )
                """
            )
            self.conn.commit()
        except sqlite3.Error as e:
            self.conn.rollback()
            raise RuntimeError(f"Failed to create table: {e}")

    def create_url(self, short_code: str, destination_url: str, expires_at: Optional[int] = None) -> bool:
        try:
            cursor = self.conn.cursor()
            cursor.execute(
                """
                INSERT INTO urls (short_code, destination_url, expires_at)
                VALUES (?, ?, ?)
                """,
                (short_code, destination_url, expires_at)
            )
            self.conn.commit()
            return True
        except sqlite3.Error as e:
            self.conn.rollback()
            return False

    def get_url_record(self, short_code: str) -> Optional[Dict[str, Union[str, int, None]]]:
        try:
            cursor = self.conn.cursor()
            cursor.execute(
                """
                SELECT short_code, destination_url, expires_at
                FROM urls
                WHERE short_code = ?
                """,
                (short_code,)
            )
            row = cursor.fetchone()
            if not row:
                return None
            return {
                "short_code": row[0],
                "destination_url": row[1],
                "expires_at": row[2]
            }
        except sqlite3.Error as e:
            return None

    def handle_redirect_request(self, short_code: str) -> Tuple[int, Union[str, Dict[str, str]]]:
        try:
            record = self.get_url_record(short_code)
            if not record:
                return 404, {"detail": "Link not found"}

            expires_at = record.get("expires_at")
            if expires_at is not None:
                current_time = int(time.time())
                if current_time > int(expires_at):
                    return 410, {"detail": "Link expired"}

            destination_url = str(record["destination_url"])
            return 302, destination_url
        except Exception as e:
            return 500, {"detail": f"Internal server error: {e}"}

    def close(self) -> None:
        try:
            if self.conn:
                self.conn.close()
        except sqlite3.Error:
            pass
